    pub friction: f32,
}

impl Default for Particle {
    fn default() -> Self {
        Self {
            velocity: Vec2::ZERO,
            acceleration: Vec2::ZERO,
            lifetime: Timer::from_seconds(1.0, TimerMode::Once),
            start_scale: 1.0,
            end_scale: 0.0,
            start_color: Color::WHITE,
            end_color: Color::srgba(1.0, 1.0, 1.0, 0.0),
            rotation_speed: 0.0,
            gravity: 0.0,
            friction: 0.98,
        }
    }
}


