//! LAN networking for the game.
//!
//! Architecture
//! ────────────
//! One machine is the **Host** (authoritative simulation, Player 1 / WASD).
//! The other is the **Client** (thin renderer + input forwarder, Player 2 / Arrow keys).
//!
//! Transport
//! ─────────
//! Plain TCP with length-prefixed frames (`u32 LE` + bincode payload).
//! Background reader/writer threads communicate with Bevy via `mpsc` channels.
//! All Bevy systems check for the optional `NetInbox`/`NetOutbox` resources so
//! the game works identically in `Solo` mode (no resources → systems are no-ops).
//!
//! Upgrade modes
//! ─────────────
//! • **Mode B – Shared** (default): any level-up pauses BOTH machines; the chosen
//!   upgrade is applied to every player's weapon set.
//! • **Mode A – Independent**: each player upgrades their own weapons separately.
//!   P1 levels up on the host machine only; P2's upgrade UI appears on the client.

use bevy::prelude::*;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::{
    io::{Read, Write},
    net::{TcpListener, TcpStream},
    sync::{
        atomic::{AtomicBool, Ordering},
        mpsc::{self, Receiver, Sender},
        Arc, Mutex,
    },
    thread,
    time::Duration,
};
use bevy::ecs::schedule::graph::Direction;
use crate::plugins::game_state::GameState;

/// TCP port the host listens on.
pub const NET_PORT: u16 = 7777;

// ─────────────────────────── Message types ───────────────────────────────

/// Messages the client sends to the host every frame / on events.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum C2S {
    /// Client P2's keyboard state this frame.
    PlayerInput(InputState),
    /// Client's P2 chose an upgrade; payload is the `WeaponType` index (0-4).
    UpgradeChosen(u8),
}

/// Messages the host sends to the client every frame / on events.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum S2C {
    /// Both players' current stats — sent every frame by the host.
    StatSnapshot(StatSnapshotMsg),
    /// A `GameState` transition the client must mirror.
    StateChange(NetworkedGameState),
    /// Upgrade options the client should present.
    /// `opts`: up to 3 `WeaponType` indices; `for_player`: 0=P1, 1=P2, 255=both.
    UpgradeOptions { opts: Vec<u8>, for_player: u8 },
    /// An upgrade was applied on the host; client must apply it too.
    /// `weapon_type`: `WeaponType` index; `for_player`: 0=P1, 1=P2, 255=both.
    UpgradeApplied { weapon_type: u8, for_player: u8 },
    /// The upgrade mode chosen in the lobby (0 = Shared, 1 = Independent).
    UpgradeMode(u8),
    // Silah efektleri client a giden
    WeaponFxSpawned {
        visual_type: VisualType,
        transform: TransformSnapshot,
        owner_net_id: Option<u32>,
    },
    // Oyuncu silahı seviye atlamaları
    WeaponStateChanged {
        net_id: u32,
        visual_type: VisualType,
        owner_net_id: u32,
    },
}

/// A compact representation of `GameState` that can be sent over the network.
/// Only the states that need to be mirrored on the client are included.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub enum NetworkedGameState {
    Playing,
    UpgradeSelection,
    GameOver,
}

impl From<NetworkedGameState> for GameState {
    fn from(s: NetworkedGameState) -> GameState {
        match s {
            NetworkedGameState::Playing => GameState::Playing,
            NetworkedGameState::UpgradeSelection => GameState::UpgradeSelection,
            NetworkedGameState::GameOver => GameState::GameOver,
        }
    }
}

/// The per-frame keyboard input the client sends to the host for P2.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct InputState {
    pub left: bool,
    pub right: bool,
    pub up: bool,
    pub down: bool,
    pub collect_magnet: bool,
}

/// Per-player stat data packed into every snapshot frame.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct PlayerStat {
    pub health: u32,
    pub xp: f32,
    pub level: i32,
    pub xp_to_next_level: f32,
    pub score: u32,
}

/// Full snapshot broadcast by the host each frame.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct StatSnapshotMsg {
    pub p1: PlayerStat,
    pub p2: PlayerStat,
    /// Positions of every replicated game entity this frame.
    pub entities: Vec<EntitySnapshot>,
    /// Host-authoritative world-space position of Player 1 `[x, y]`.
    pub p1_pos: [f32; 2],
    /// Host-authoritative world-space position of Player 2 `[x, y]`.
    pub p2_pos: [f32; 2],
    /// Host-authoritative elapsed game time in seconds.
    /// The client overwrites its local `GameTimer` with this value every frame.
    pub game_elapsed_secs: f32,
}

// ─────────────────────────── Generic entity replication ──────────────────

/// Marks a game entity that the host should replicate to connected clients.
///
/// Carries both the stable per-session network identifier **and** the visual
/// class the client needs in order to decide which sprite / mesh to draw.
#[derive(Component, Clone, Copy, Debug, PartialEq)]
pub struct NetworkIdentity {
    /// Monotonically increasing ID assigned by the host at spawn time.
    pub net_id: u32,
    /// Visual class — consumed by the client sync system to choose a renderer.
    pub visual_type: VisualType,
}

/// Monotonic counter that the host uses to hand out unique `NetworkIdentity` IDs.
/// Only meaningful on the host / solo machine.
#[derive(Resource, Default)]
pub struct NetIdCounter(pub u32);

impl NetIdCounter {
    /// Advance and return the next available ID (starts at 1).
    pub fn next(&mut self) -> u32 {
        self.0 += 1;
        self.0
    }
}

// drain_inbox içine S2C::WeaponFxSpawned ve S2C::WeaponStateChanged geldiğinde bu listeye pushlayın.#[derive(Resource, Default)]
#[derive(Resource, Default)]
pub struct PendingWeaponFxEvents(pub Vec<S2C>);
#[derive(Resource, Default)]
pub struct PendingWeaponStateEvents(pub Vec<S2C>);

/// The visual class of a replicated entity.
///
/// The client inspects this value to decide which sprite or mesh to render.
/// No game logic (physics, damage, AI) is ever derived from it on the client.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq)]
pub enum VisualType {
    // ── Enemies ──────────────────────────────────────────────────────────
    Zombie,
    Knight,
    Vampire,
    Robot,
    // ── Collectibles ─────────────────────────────────────────────────────
    XpGem,
    HealthPack,
    AtomBomb,
    Magnet,
    // ── Weapon projectiles / effects ─────────────────────────────────────
    LaserProjectile,
    RocketProjectile,
    SwordWeapon,
    RayGunRay,
    FlameAura,
    // ── VFX (Event based)
    MuzzleFlash {direction: Vec3},
    Explosion {radius: f32},
    Trail,
}

/// Compact transform representation safe to send over the wire.
///
/// Plain arrays avoid the need for any extra serde feature flags on glam/bevy.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, Default)]
pub struct TransformSnapshot {
    /// World-space translation `[x, y, z]`.
    pub translation: [f32; 3],
    /// Orientation as a unit quaternion `[x, y, z, w]`.
    pub rotation: [f32; 4],
    /// Non-uniform scale `[x, y, z]`.
    pub scale: [f32; 3],
}

impl TransformSnapshot {
    /// Compress a Bevy `Transform` into a `TransformSnapshot`.
    pub fn from_transform(t: &Transform) -> Self {
        Self {
            translation: [t.translation.x, t.translation.y, t.translation.z],
            rotation: [t.rotation.x, t.rotation.y, t.rotation.z, t.rotation.w],
            scale: [t.scale.x, t.scale.y, t.scale.z],
        }
    }

    /// Reconstruct a Bevy `Transform` from a `TransformSnapshot`.
    pub fn to_transform(self) -> Transform {
        Transform {
            translation: Vec3::new(self.translation[0], self.translation[1], self.translation[2]),
            rotation: Quat::from_xyzw(
                self.rotation[0],
                self.rotation[1],
                self.rotation[2],
                self.rotation[3],
            ),
            scale: Vec3::new(self.scale[0], self.scale[1], self.scale[2]),
        }
    }
}

/// One replicated entity's network snapshot: stable ID, visual class, and pose.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct EntitySnapshot {
    /// Stable ID assigned by the host when the entity was spawned.
    pub net_id: u32,
    /// What this entity looks like — used by the client to choose a visual.
    pub visual_type: VisualType,
    /// Current world-space transform.
    pub transform: TransformSnapshot,
}

// ──────────────────────────── Upgrade mode ───────────────────────────────

/// Upgrade mode selected by the host in the lobby.
#[derive(Serialize, Deserialize, Resource, Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum UpgradeMode {
    /// Mode B – one shared upgrade choice is applied to both players simultaneously.
    #[default]
    Shared,
    /// Mode A – each player upgrades their own character independently.
    Independent,
}

impl UpgradeMode {
    pub fn to_u8(self) -> u8 {
        match self {
            UpgradeMode::Shared => 0,
            UpgradeMode::Independent => 1,
        }
    }
    pub fn from_u8(v: u8) -> Self {
        if v == 1 {
            UpgradeMode::Independent
        } else {
            UpgradeMode::Shared
        }
    }
}

// ──────────────────────────── Network role ───────────────────────────────

/// Whether this app instance is running as host, client, or standalone.
#[derive(Resource, Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum NetworkRole {
    /// No networking — two local players on one machine (original behaviour).
    #[default]
    Solo,
    Host,
    Client,
}

// ─────────────────────────── Bevy resources ──────────────────────────────

/// Sender end: game systems queue outgoing byte frames here.
#[derive(Resource)]
pub struct NetOutbox(pub Sender<Vec<u8>>);

/// Receiver end: the reader thread pushes incoming byte frames here each frame.
#[derive(Resource)]
pub struct NetInbox(pub Mutex<Receiver<Vec<u8>>>);

/// The most recent P2 input received from the client.
/// Only meaningful on the host.
#[derive(Resource, Default)]
pub struct RemoteInput(pub InputState);

/// Set while a background TCP connection attempt is still in progress.
#[derive(Resource)]
pub struct PendingConnection {
    /// Becomes `true` when the connection is established.
    pub ready: Arc<AtomicBool>,
    /// Once `ready`, contains the channel pair to hand to Bevy.
    pub channels: Arc<Mutex<Option<(Sender<Vec<u8>>, Receiver<Vec<u8>>)>>>,
}

// ────────────── Pending-message resources (populated by drain_inbox) ─────

/// Latest stat snapshot from the host; consumed by `player.rs`.
#[derive(Resource, Default)]
pub struct PendingStatSnapshot(pub Option<StatSnapshotMsg>);

/// Upgrade options pushed by the host; consumed by `weapon_upgrade.rs`.
/// `(weapon_type_indices, for_player)`.
#[derive(Resource, Default)]
pub struct PendingUpgradeOptions(pub Option<(Vec<u8>, u8)>);

/// Upgrade-applied notification from the host; consumed by `weapon_upgrade.rs`.
/// `(weapon_type_index, for_player)`.
#[derive(Resource, Default)]
pub struct PendingUpgradeApplied(pub Option<(u8, u8)>);

/// Upgrade choice received from the client (P2); consumed by `weapon_upgrade.rs`.
/// Only populated on the host. Value is a `WeaponType` index.
#[derive(Resource, Default)]
pub struct PendingClientUpgradeChoice(pub Option<u8>);

/// Game-state change received from the host; applied by `apply_pending_state`.
#[derive(Resource, Default)]
pub struct PendingStateChange(pub Option<NetworkedGameState>);

/// The most recent entity-snapshot list received from the host.
/// Consumed each frame by the client's unified sync system.
#[derive(Resource, Default)]
pub struct PendingEntitySnapshots(pub Vec<EntitySnapshot>);

// ─────────────────────────── Client ghost tracking ───────────────────────

/// Marks a client-side ghost entity created by the sync system.
///
/// The wrapped value is the `net_id` of the corresponding host entity.
/// Ghost entities carry **only** visual components — no physics, damage, or AI.
#[derive(Component, Clone, Copy, Debug)]
pub struct GhostEntity(pub u32);

/// Maps `net_id → client Entity` for all live ghost entities.
///
/// Updated every frame by `client_entity_sync`.
/// Only meaningful on the client machine.
#[derive(Resource, Default)]
pub struct ClientEntityMap(pub HashMap<u32, Entity>);

// ─────────────────────────── Plugin ──────────────────────────────────────

pub struct NetworkPlugin;

impl Plugin for NetworkPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<NetworkRole>()
            .init_resource::<UpgradeMode>()
            .init_resource::<RemoteInput>()
            .init_resource::<NetIdCounter>()
            .init_resource::<PendingStatSnapshot>()
            .init_resource::<PendingEntitySnapshots>()
            .init_resource::<ClientEntityMap>()
            .init_resource::<PendingUpgradeOptions>()
            .init_resource::<PendingUpgradeApplied>()
            .init_resource::<PendingClientUpgradeChoice>()
            .init_resource::<PendingStateChange>()
            .init_resource::<PendingWeaponStateEvents>()
            .init_resource::<PendingWeaponFxEvents>()
            .add_systems(
                Update,
                (
                    poll_pending_connection,
                    drain_inbox,
                    apply_pending_state,
                ),
            );
    }
}

// ────────────────────────── TCP framing helpers ───────────────────────────

/// Serialise `msg` into a `u32-LE length` + bincode payload frame.
pub fn encode<T: Serialize>(msg: &T) -> Result<Vec<u8>, bincode::Error> {
    let payload = bincode::serialize(msg)?;
    let len = payload.len() as u32;
    let mut frame = len.to_le_bytes().to_vec();
    frame.extend(payload);
    Ok(frame)
}

/// Read exactly `n` bytes from the stream (blocking).
fn read_exact(stream: &mut TcpStream, n: usize) -> std::io::Result<Vec<u8>> {
    let mut buf = vec![0u8; n];
    stream.read_exact(&mut buf)?;
    Ok(buf)
}

// ─────────────────────────── Background threads ──────────────────────────

/// Spawn a reader and a writer background thread for an established TCP stream.
///
/// Returns `(outbox_tx, inbox_rx)`:
/// - Push encoded frames into `outbox_tx` to send them.
/// - Pull received frames from `inbox_rx`.
fn spawn_net_threads(stream: TcpStream) -> (Sender<Vec<u8>>, Receiver<Vec<u8>>) {
    let (inbox_tx, inbox_rx) = mpsc::channel::<Vec<u8>>();
    let (outbox_tx, outbox_rx) = mpsc::channel::<Vec<u8>>();

    let mut read_stream = stream.try_clone().expect("TcpStream clone failed");
    let mut write_stream = stream;

    // Reader: length-prefix decode → push to inbox_tx
    thread::spawn(move || loop {
        let len_bytes = match read_exact(&mut read_stream, 4) {
            Ok(b) => b,
            Err(_) => break,
        };
        let len =
            u32::from_le_bytes([len_bytes[0], len_bytes[1], len_bytes[2], len_bytes[3]]) as usize;
        // Sanity guard: skip absurdly large frames (> 1 MiB)
        if len == 0 || len > 1_048_576 {
            break;
        }
        match read_exact(&mut read_stream, len) {
            Ok(payload) => {
                if inbox_tx.send(payload).is_err() {
                    break;
                }
            }
            Err(_) => break,
        }
    });

    // Writer: drain outbox_rx → send frames
    thread::spawn(move || {
        while let Ok(frame) = outbox_rx.recv() {
            if write_stream.write_all(&frame).is_err() {
                break;
            }
        }
    });

    (outbox_tx, inbox_rx)
}

// ────────────────────────── Host / Client startup ────────────────────────

/// Start a TCP listener in a background thread and wait for exactly one client.
/// Returns a `PendingConnection`; poll `ready` in a Bevy system.
pub fn start_host() -> PendingConnection {
    let ready = Arc::new(AtomicBool::new(false));
    let channels = Arc::new(Mutex::new(
        None::<(Sender<Vec<u8>>, Receiver<Vec<u8>>)>,
    ));

    let ready2 = ready.clone();
    let channels2 = channels.clone();

    thread::spawn(move || {
        let listener = match TcpListener::bind(format!("0.0.0.0:{NET_PORT}")) {
            Ok(l) => l,
            Err(e) => {
                eprintln!("[host] bind failed: {e}");
                return;
            }
        };
        println!("[host] listening on :{NET_PORT}");
        match listener.accept() {
            Ok((stream, addr)) => {
                println!("[host] client connected from {addr}");
                let (tx, rx) = spawn_net_threads(stream);
                *channels2.lock().unwrap() = Some((tx, rx));
                ready2.store(true, Ordering::Release);
            }
            Err(e) => eprintln!("[host] accept error: {e}"),
        }
    });

    PendingConnection { ready, channels }
}

/// Connect to `host_ip` in a background thread (retries up to 10 times).
/// Returns a `PendingConnection`; poll `ready` in a Bevy system.
pub fn start_client(host_ip: String) -> PendingConnection {
    let ready = Arc::new(AtomicBool::new(false));
    let channels = Arc::new(Mutex::new(
        None::<(Sender<Vec<u8>>, Receiver<Vec<u8>>)>,
    ));

    let ready2 = ready.clone();
    let channels2 = channels.clone();

    thread::spawn(move || {
        let addr = format!("{host_ip}:{NET_PORT}");
        println!("[client] connecting to {addr}");
        for attempt in 0..10u32 {
            match TcpStream::connect(&addr) {
                Ok(stream) => {
                    println!("[client] connected to host");
                    let (tx, rx) = spawn_net_threads(stream);
                    *channels2.lock().unwrap() = Some((tx, rx));
                    ready2.store(true, Ordering::Release);
                    return;
                }
                Err(e) => {
                    if attempt < 9 {
                        thread::sleep(Duration::from_millis(500));
                    } else {
                        eprintln!("[client] connect failed after {attempt} attempts: {e}");
                    }
                }
            }
        }
    });

    PendingConnection { ready, channels }
}

// ─────────────────────────── Bevy systems ────────────────────────────────

/// Poll `PendingConnection` and, when ready, promote to `NetInbox`/`NetOutbox`.
///
/// The host immediately sends the chosen `UpgradeMode` to the client and
/// transitions both machines to `GameState::Loading`.
fn poll_pending_connection(
    pending: Option<ResMut<PendingConnection>>,
    mut commands: Commands,
    role: Res<NetworkRole>,
    upgrade_mode: Res<UpgradeMode>,
    mut next_state: ResMut<NextState<GameState>>,
) {
    let Some(mut pending) = pending else {
        return;
    };
    if !pending.ready.load(Ordering::Acquire) {
        return;
    }
    let Some((tx, rx)) = pending.channels.lock().unwrap().take() else {
        return;
    };

    let tx2 = tx.clone();
    commands.insert_resource(NetOutbox(tx));
    commands.insert_resource(NetInbox(Mutex::new(rx)));
    commands.remove_resource::<PendingConnection>();

    match *role {
        NetworkRole::Host => {
            // Send the upgrade mode to the client before the game starts.
            if let Ok(frame) = encode(&S2C::UpgradeMode(upgrade_mode.to_u8())) {
                let _ = tx2.send(frame);
            }
            next_state.set(GameState::Loading);
        }
        NetworkRole::Client => {
            // Upgrade mode arrives asynchronously; transition after it lands.
            // The client transitions to Loading immediately; the upgrade mode
            // resource is updated in `drain_inbox` as soon as the message arrives.
            next_state.set(GameState::Loading);
        }
        NetworkRole::Solo => {}
    }
}

/// Drain the `NetInbox` and populate the appropriate `Pending*` resources.
///
/// The actual application of each pending value happens in dedicated systems
/// inside the relevant plugins, keeping concerns separated.
fn drain_inbox(
    inbox: Option<Res<NetInbox>>,
    role: Res<NetworkRole>,
    mut remote_input: ResMut<RemoteInput>,
    mut upgrade_mode: ResMut<UpgradeMode>,
    mut pending_snap: ResMut<PendingStatSnapshot>,
    mut pending_entity_snaps: ResMut<PendingEntitySnapshots>,
    mut pending_opts: ResMut<PendingUpgradeOptions>,
    mut pending_applied: ResMut<PendingUpgradeApplied>,
    mut pending_client_choice: ResMut<PendingClientUpgradeChoice>,
    mut pending_state: ResMut<PendingStateChange>,
    mut pending_weapon_fx_events: ResMut<PendingWeaponFxEvents>,
    mut pending_weapon_state_events: ResMut<PendingWeaponStateEvents>,
) {
    let Some(inbox) = inbox else {
        return;
    };
    let rx = inbox.0.lock().unwrap();

    while let Ok(bytes) = rx.try_recv() {
        match *role {
            NetworkRole::Host => {
                if let Ok(msg) = bincode::deserialize::<C2S>(&bytes) {
                    match msg {
                        C2S::PlayerInput(input) => {
                            remote_input.0 = input;
                        }
                        C2S::UpgradeChosen(idx) => {
                            pending_client_choice.0 = Some(idx);
                        }
                    }
                }
            }
            NetworkRole::Client => {
                if let Ok(msg) = bincode::deserialize::<S2C>(&bytes) {
                    match msg {
                        S2C::UpgradeMode(mode_byte) => {
                            *upgrade_mode = UpgradeMode::from_u8(mode_byte);
                        }
                        S2C::StatSnapshot(snap) => {
                            // Stash entity snapshots separately for the sync system.
                            pending_entity_snaps.0 = snap.entities.clone();
                            pending_snap.0 = Some(snap);
                        }
                        S2C::StateChange(new_state) => {
                            pending_state.0 = Some(new_state);
                        }
                        S2C::UpgradeOptions { opts, for_player } => {
                            pending_opts.0 = Some((opts, for_player));
                        }
                        S2C::UpgradeApplied {
                            weapon_type,
                            for_player,
                        } => {
                            pending_applied.0 = Some((weapon_type, for_player));
                        }
                        S2C::WeaponFxSpawned {
                            visual_type,
                            transform,
                            owner_net_id,
                        } => {
                            pending_weapon_fx_events.0.push(S2C::WeaponFxSpawned {
                                visual_type,
                                transform,
                                owner_net_id,
                            });
                        }
                        S2C::WeaponStateChanged {
                            net_id,
                            visual_type,
                            owner_net_id,
                        } => {
                            pending_weapon_state_events.0.push(S2C::WeaponStateChanged {
                                net_id,
                                visual_type,
                                owner_net_id,
                            })
                        }
                    }
                }
            }
            NetworkRole::Solo => {}
        }
    }
}

/// Apply a pending game-state change (received from the host) on the client.
fn apply_pending_state(
    role: Res<NetworkRole>,
    mut pending: ResMut<PendingStateChange>,
    mut next_state: ResMut<NextState<GameState>>,
) {
    if *role != NetworkRole::Client {
        return;
    }
    if let Some(new_state) = pending.0.take() {
        next_state.set(new_state.into());
    }
}

//! LAN networking for the game.
//!
//! Architecture
//! ────────────
//! One machine is the **Host** (authoritative simulation, Player 1 / WASD).
//! The other is the **Client** (thin renderer + input forwarder, Player 2 / Arrow keys).
//!
//! Transport
//! ─────────
//! Plain TCP with length-prefixed frames (`u32 LE` + bincode payload).
//! Background reader/writer threads communicate with Bevy via `mpsc` channels.
//! All Bevy systems check for the optional `NetInbox`/`NetOutbox` resources so
//! the game works identically in `Solo` mode (no resources → systems are no-ops).
//!
//! Upgrade modes
//! ─────────────
//! • **Mode B – Shared** (default): any level-up pauses BOTH machines; the chosen
//!   upgrade is applied to every player's weapon set.
//! • **Mode A – Independent**: each player upgrades their own weapons separately.
//!   P1 levels up on the host machine only; P2's upgrade UI appears on the client.

use bevy::prelude::*;
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::{
    io::{Read, Write},
    net::{TcpListener, TcpStream},
    sync::{
        atomic::{AtomicBool, Ordering},
        mpsc::{self, Receiver, Sender},
        Arc, Mutex,
    },
    thread,
    time::Duration,
};
use bevy::ecs::schedule::graph::Direction;
use crate::plugins::game_state::GameState;

/// TCP port the host listens on.
pub const NET_PORT: u16 = 7777;

// ─────────────────────────── Message types ───────────────────────────────

/// Messages the client sends to the host every frame / on events.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum C2S {
    /// Client P2's keyboard state this frame.
    PlayerInput(InputState),
    /// Client's P2 chose an upgrade; payload is the `WeaponType` index (0-4).
    UpgradeChosen(u8),
}

/// Messages the host sends to the client every frame / on events.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum S2C {
    /// Both players' current stats — sent every frame by the host.
    StatSnapshot(StatSnapshotMsg),
    /// A `GameState` transition the client must mirror.
    StateChange(NetworkedGameState),
    /// Upgrade options the client should present.
    /// `opts`: up to 3 `WeaponType` indices; `for_player`: 0=P1, 1=P2, 255=both.
    UpgradeOptions { opts: Vec<u8>, for_player: u8 },
    /// An upgrade was applied on the host; client must apply it too.
    /// `weapon_type`: `WeaponType` index; `for_player`: 0=P1, 1=P2, 255=both.
    UpgradeApplied { weapon_type: u8, for_player: u8 },
    /// The upgrade mode chosen in the lobby (0 = Shared, 1 = Independent).
    UpgradeMode(u8),
    // Silah efektleri client a giden
    WeaponFxSpawned {
        visual_type: VisualType,
        transform: TransformSnapshot,
        owner_net_id: Option<u32>,
    },
    // Oyuncu silahı seviye atlamaları
    WeaponStateChanged {
        net_id: u32,
        visual_type: VisualType,
        owner_net_id: u32,
    },
}

/// A compact representation of `GameState` that can be sent over the network.
/// Only the states that need to be mirrored on the client are included.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub enum NetworkedGameState {
    Playing,
    UpgradeSelection,
    GameOver,
}

impl From<NetworkedGameState> for GameState {
    fn from(s: NetworkedGameState) -> GameState {
        match s {
            NetworkedGameState::Playing => GameState::Playing,
            NetworkedGameState::UpgradeSelection => GameState::UpgradeSelection,
            NetworkedGameState::GameOver => GameState::GameOver,
        }
    }
}

/// The per-frame keyboard input the client sends to the host for P2.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct InputState {
    pub left: bool,
    pub right: bool,
    pub up: bool,
    pub down: bool,
    pub collect_magnet: bool,
    pub mouse_world_pos: Option<[f32; 2]>,
}

/// Per-player stat data packed into every snapshot frame.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct PlayerStat {
    pub health: u32,
    pub xp: f32,
    pub level: i32,
    pub xp_to_next_level: f32,
    pub score: u32,
}

/// Full snapshot broadcast by the host each frame.
#[derive(Serialize, Deserialize, Clone, Debug, Default)]
pub struct StatSnapshotMsg {
    pub p1: PlayerStat,
    pub p2: PlayerStat,
    /// Positions of every replicated game entity this frame.
    pub entities: Vec<EntitySnapshot>,
    /// Host-authoritative world-space position of Player 1 `[x, y]`.
    pub p1_pos: [f32; 2],
    /// Host-authoritative world-space position of Player 2 `[x, y]`.
    pub p2_pos: [f32; 2],
    /// Host-authoritative elapsed game time in seconds.
    /// The client overwrites its local `GameTimer` with this value every frame.
    pub game_elapsed_secs: f32,
}

// ─────────────────────────── Generic entity replication ──────────────────

/// Marks a game entity that the host should replicate to connected clients.
///
/// Carries both the stable per-session network identifier **and** the visual
/// class the client needs in order to decide which sprite / mesh to draw.
#[derive(Component, Clone, Copy, Debug, PartialEq)]
pub struct NetworkIdentity {
    /// Monotonically increasing ID assigned by the host at spawn time.
    pub net_id: u32,
    /// Visual class — consumed by the client sync system to choose a renderer.
    pub visual_type: VisualType,
}

/// Monotonic counter that the host uses to hand out unique `NetworkIdentity` IDs.
/// Only meaningful on the host / solo machine.
#[derive(Resource, Default)]
pub struct NetIdCounter(pub u32);

impl NetIdCounter {
    /// Advance and return the next available ID (starts at 1).
    pub fn next(&mut self) -> u32 {
        self.0 += 1;
        self.0
    }
}

// drain_inbox içine S2C::WeaponFxSpawned ve S2C::WeaponStateChanged geldiğinde bu listeye pushlayın.#[derive(Resource, Default)]
#[derive(Resource, Default)]
pub struct PendingWeaponFxEvents(pub Vec<S2C>);
#[derive(Resource, Default)]
pub struct PendingWeaponStateEvents(pub Vec<S2C>);

/// The visual class of a replicated entity.
///
/// The client inspects this value to decide which sprite or mesh to render.
/// No game logic (physics, damage, AI) is ever derived from it on the client.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq)]
pub enum VisualType {
    // ── Enemies ──────────────────────────────────────────────────────────
    Zombie,
    Knight,
    Vampire,
    Robot,
    // ── Collectibles ─────────────────────────────────────────────────────
    XpGem,
    HealthPack,
    AtomBomb,
    Magnet,
    // ── Weapon projectiles / effects ─────────────────────────────────────
    LaserProjectile,
    RocketProjectile,
    SwordWeapon,
    RayGunRay,
    FlameAura,
    // ── VFX (Event based)
    MuzzleFlash {direction: Vec3},
    Explosion {radius: f32},
    Trail,
}

/// Compact transform representation safe to send over the wire.
///
/// Plain arrays avoid the need for any extra serde feature flags on glam/bevy.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, Default)]
pub struct TransformSnapshot {
    /// World-space translation `[x, y, z]`.
    pub translation: [f32; 3],
    /// Orientation as a unit quaternion `[x, y, z, w]`.
    pub rotation: [f32; 4],
    /// Non-uniform scale `[x, y, z]`.
    pub scale: [f32; 3],
}

impl TransformSnapshot {
    /// Compress a Bevy `Transform` into a `TransformSnapshot`.
    pub fn from_transform(t: &Transform) -> Self {
        Self {
            translation: [t.translation.x, t.translation.y, t.translation.z],
            rotation: [t.rotation.x, t.rotation.y, t.rotation.z, t.rotation.w],
            scale: [t.scale.x, t.scale.y, t.scale.z],
        }
    }

    /// Reconstruct a Bevy `Transform` from a `TransformSnapshot`.
    pub fn to_transform(self) -> Transform {
        Transform {
            translation: Vec3::new(self.translation[0], self.translation[1], self.translation[2]),
            rotation: Quat::from_xyzw(
                self.rotation[0],
                self.rotation[1],
                self.rotation[2],
                self.rotation[3],
            ),
            scale: Vec3::new(self.scale[0], self.scale[1], self.scale[2]),
        }
    }
}

/// One replicated entity's network snapshot: stable ID, visual class, and pose.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct EntitySnapshot {
    /// Stable ID assigned by the host when the entity was spawned.
    pub net_id: u32,
    /// What this entity looks like — used by the client to choose a visual.
    pub visual_type: VisualType,
    /// Current world-space transform.
    pub transform: TransformSnapshot,
}

// ──────────────────────────── Upgrade mode ───────────────────────────────

/// Upgrade mode selected by the host in the lobby.
#[derive(Serialize, Deserialize, Resource, Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum UpgradeMode {
    /// Mode B – one shared upgrade choice is applied to both players simultaneously.
    #[default]
    Shared,
    /// Mode A – each player upgrades their own character independently.
    Independent,
}

impl UpgradeMode {
    pub fn to_u8(self) -> u8 {
        match self {
            UpgradeMode::Shared => 0,
            UpgradeMode::Independent => 1,
        }
    }
    pub fn from_u8(v: u8) -> Self {
        if v == 1 {
            UpgradeMode::Independent
        } else {
            UpgradeMode::Shared
        }
    }
}

// ──────────────────────────── Network role ───────────────────────────────

/// Whether this app instance is running as host, client, or standalone.
#[derive(Resource, Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum NetworkRole {
    /// No networking — two local players on one machine (original behaviour).
    #[default]
    Solo,
    Host,
    Client,
}

// ─────────────────────────── Bevy resources ──────────────────────────────

/// Sender end: game systems queue outgoing byte frames here.
#[derive(Resource)]
pub struct NetOutbox(pub Sender<Vec<u8>>);

/// Receiver end: the reader thread pushes incoming byte frames here each frame.
#[derive(Resource)]
pub struct NetInbox(pub Mutex<Receiver<Vec<u8>>>);

/// The most recent P2 input received from the client.
/// Only meaningful on the host.
#[derive(Resource, Default)]
pub struct RemoteInput(pub InputState);

/// Set while a background TCP connection attempt is still in progress.
#[derive(Resource)]
pub struct PendingConnection {
    /// Becomes `true` when the connection is established.
    pub ready: Arc<AtomicBool>,
    /// Once `ready`, contains the channel pair to hand to Bevy.
    pub channels: Arc<Mutex<Option<(Sender<Vec<u8>>, Receiver<Vec<u8>>)>>>,
}

// ────────────── Pending-message resources (populated by drain_inbox) ─────

/// Latest stat snapshot from the host; consumed by `player.rs`.
#[derive(Resource, Default)]
pub struct PendingStatSnapshot(pub Option<StatSnapshotMsg>);

/// Upgrade options pushed by the host; consumed by `weapon_upgrade.rs`.
/// `(weapon_type_indices, for_player)`.
#[derive(Resource, Default)]
pub struct PendingUpgradeOptions(pub Option<(Vec<u8>, u8)>);

/// Upgrade-applied notification from the host; consumed by `weapon_upgrade.rs`.
/// `(weapon_type_index, for_player)`.
#[derive(Resource, Default)]
pub struct PendingUpgradeApplied(pub Option<(u8, u8)>);

/// Upgrade choice received from the client (P2); consumed by `weapon_upgrade.rs`.
/// Only populated on the host. Value is a `WeaponType` index.
#[derive(Resource, Default)]
pub struct PendingClientUpgradeChoice(pub Option<u8>);

/// Game-state change received from the host; applied by `apply_pending_state`.
#[derive(Resource, Default)]
pub struct PendingStateChange(pub Option<NetworkedGameState>);

/// The most recent entity-snapshot list received from the host.
/// Consumed each frame by the client's unified sync system.
#[derive(Resource, Default)]
pub struct PendingEntitySnapshots(pub Vec<EntitySnapshot>);

// ─────────────────────────── Client ghost tracking ───────────────────────

/// Marks a client-side ghost entity created by the sync system.
///
/// The wrapped value is the `net_id` of the corresponding host entity.
/// Ghost entities carry **only** visual components — no physics, damage, or AI.
#[derive(Component, Clone, Copy, Debug)]
pub struct GhostEntity(pub u32);

/// Maps `net_id → client Entity` for all live ghost entities.
///
/// Updated every frame by `client_entity_sync`.
/// Only meaningful on the client machine.
#[derive(Resource, Default)]
pub struct ClientEntityMap(pub HashMap<u32, Entity>);

// ─────────────────────────── Plugin ──────────────────────────────────────

pub struct NetworkPlugin;

impl Plugin for NetworkPlugin {
    fn build(&self, app: &mut App) {
        app.init_resource::<NetworkRole>()
            .init_resource::<UpgradeMode>()
            .init_resource::<RemoteInput>()
            .init_resource::<NetIdCounter>()
            .init_resource::<PendingStatSnapshot>()
            .init_resource::<PendingEntitySnapshots>()
            .init_resource::<ClientEntityMap>()
            .init_resource::<PendingUpgradeOptions>()
            .init_resource::<PendingUpgradeApplied>()
            .init_resource::<PendingClientUpgradeChoice>()
            .init_resource::<PendingStateChange>()
            .init_resource::<PendingWeaponStateEvents>()
            .init_resource::<PendingWeaponFxEvents>()
            .add_systems(
                Update,
                (
                    poll_pending_connection,
                    drain_inbox,
                    apply_pending_state,
                ),
            );
    }
}

// ────────────────────────── TCP framing helpers ───────────────────────────

/// Serialise `msg` into a `u32-LE length` + bincode payload frame.
pub fn encode<T: Serialize>(msg: &T) -> Result<Vec<u8>, bincode::Error> {
    let payload = bincode::serialize(msg)?;
    let len = payload.len() as u32;
    let mut frame = len.to_le_bytes().to_vec();
    frame.extend(payload);
    Ok(frame)
}

/// Read exactly `n` bytes from the stream (blocking).
fn read_exact(stream: &mut TcpStream, n: usize) -> std::io::Result<Vec<u8>> {
    let mut buf = vec![0u8; n];
    stream.read_exact(&mut buf)?;
    Ok(buf)
}

// ─────────────────────────── Background threads ──────────────────────────

/// Spawn a reader and a writer background thread for an established TCP stream.
///
/// Returns `(outbox_tx, inbox_rx)`:
/// - Push encoded frames into `outbox_tx` to send them.
/// - Pull received frames from `inbox_rx`.
fn spawn_net_threads(stream: TcpStream) -> (Sender<Vec<u8>>, Receiver<Vec<u8>>) {
    let (inbox_tx, inbox_rx) = mpsc::channel::<Vec<u8>>();
    let (outbox_tx, outbox_rx) = mpsc::channel::<Vec<u8>>();

    let mut read_stream = stream.try_clone().expect("TcpStream clone failed");
    let mut write_stream = stream;

    // Reader: length-prefix decode → push to inbox_tx
    thread::spawn(move || loop {
        let len_bytes = match read_exact(&mut read_stream, 4) {
            Ok(b) => b,
            Err(_) => break,
        };
        let len =
            u32::from_le_bytes([len_bytes[0], len_bytes[1], len_bytes[2], len_bytes[3]]) as usize;
        // Sanity guard: skip absurdly large frames (> 1 MiB)
        if len == 0 || len > 1_048_576 {
            break;
        }
        match read_exact(&mut read_stream, len) {
            Ok(payload) => {
                if inbox_tx.send(payload).is_err() {
                    break;
                }
            }
            Err(_) => break,
        }
    });

    // Writer: drain outbox_rx → send frames
    thread::spawn(move || {
        while let Ok(frame) = outbox_rx.recv() {
            if write_stream.write_all(&frame).is_err() {
                break;
            }
        }
    });

    (outbox_tx, inbox_rx)
}

// ────────────────────────── Host / Client startup ────────────────────────

/// Start a TCP listener in a background thread and wait for exactly one client.
/// Returns a `PendingConnection`; poll `ready` in a Bevy system.
pub fn start_host() -> PendingConnection {
    let ready = Arc::new(AtomicBool::new(false));
    let channels = Arc::new(Mutex::new(
        None::<(Sender<Vec<u8>>, Receiver<Vec<u8>>)>,
    ));

    let ready2 = ready.clone();
    let channels2 = channels.clone();

    thread::spawn(move || {
        let listener = match TcpListener::bind(format!("0.0.0.0:{NET_PORT}")) {
            Ok(l) => l,
            Err(e) => {
                eprintln!("[host] bind failed: {e}");
                return;
            }
        };
        println!("[host] listening on :{NET_PORT}");
        match listener.accept() {
            Ok((stream, addr)) => {
                println!("[host] client connected from {addr}");
                let (tx, rx) = spawn_net_threads(stream);
                *channels2.lock().unwrap() = Some((tx, rx));
                ready2.store(true, Ordering::Release);
            }
            Err(e) => eprintln!("[host] accept error: {e}"),
        }
    });

    PendingConnection { ready, channels }
}

/// Connect to `host_ip` in a background thread (retries up to 10 times).
/// Returns a `PendingConnection`; poll `ready` in a Bevy system.
pub fn start_client(host_ip: String) -> PendingConnection {
    let ready = Arc::new(AtomicBool::new(false));
    let channels = Arc::new(Mutex::new(
        None::<(Sender<Vec<u8>>, Receiver<Vec<u8>>)>,
    ));

    let ready2 = ready.clone();
    let channels2 = channels.clone();

    thread::spawn(move || {
        let addr = format!("{host_ip}:{NET_PORT}");
        println!("[client] connecting to {addr}");
        for attempt in 0..10u32 {
            match TcpStream::connect(&addr) {
                Ok(stream) => {
                    println!("[client] connected to host");
                    let (tx, rx) = spawn_net_threads(stream);
                    *channels2.lock().unwrap() = Some((tx, rx));
                    ready2.store(true, Ordering::Release);
                    return;
                }
                Err(e) => {
                    if attempt < 9 {
                        thread::sleep(Duration::from_millis(500));
                    } else {
                        eprintln!("[client] connect failed after {attempt} attempts: {e}");
                    }
                }
            }
        }
    });

    PendingConnection { ready, channels }
}

// ─────────────────────────── Bevy systems ────────────────────────────────

/// Poll `PendingConnection` and, when ready, promote to `NetInbox`/`NetOutbox`.
///
/// The host immediately sends the chosen `UpgradeMode` to the client and
/// transitions both machines to `GameState::Loading`.
fn poll_pending_connection(
    pending: Option<ResMut<PendingConnection>>,
    mut commands: Commands,
    role: Res<NetworkRole>,
    upgrade_mode: Res<UpgradeMode>,
    mut next_state: ResMut<NextState<GameState>>,
) {
    let Some(mut pending) = pending else {
        return;
    };
    if !pending.ready.load(Ordering::Acquire) {
        return;
    }
    let Some((tx, rx)) = pending.channels.lock().unwrap().take() else {
        return;
    };

    let tx2 = tx.clone();
    commands.insert_resource(NetOutbox(tx));
    commands.insert_resource(NetInbox(Mutex::new(rx)));
    commands.remove_resource::<PendingConnection>();

    match *role {
        NetworkRole::Host => {
            // Send the upgrade mode to the client before the game starts.
            if let Ok(frame) = encode(&S2C::UpgradeMode(upgrade_mode.to_u8())) {
                let _ = tx2.send(frame);
            }
            next_state.set(GameState::Loading);
        }
        NetworkRole::Client => {
            // Upgrade mode arrives asynchronously; transition after it lands.
            // The client transitions to Loading immediately; the upgrade mode
            // resource is updated in `drain_inbox` as soon as the message arrives.
            next_state.set(GameState::Loading);
        }
        NetworkRole::Solo => {}
    }
}

/// Drain the `NetInbox` and populate the appropriate `Pending*` resources.
///
/// The actual application of each pending value happens in dedicated systems
/// inside the relevant plugins, keeping concerns separated.
fn drain_inbox(
    inbox: Option<Res<NetInbox>>,
    role: Res<NetworkRole>,
    mut remote_input: ResMut<RemoteInput>,
    mut upgrade_mode: ResMut<UpgradeMode>,
    mut pending_snap: ResMut<PendingStatSnapshot>,
    mut pending_entity_snaps: ResMut<PendingEntitySnapshots>,
    mut pending_opts: ResMut<PendingUpgradeOptions>,
    mut pending_applied: ResMut<PendingUpgradeApplied>,
    mut pending_client_choice: ResMut<PendingClientUpgradeChoice>,
    mut pending_state: ResMut<PendingStateChange>,
    mut pending_weapon_fx_events: ResMut<PendingWeaponFxEvents>,
    mut pending_weapon_state_events: ResMut<PendingWeaponStateEvents>,
) {
    let Some(inbox) = inbox else {
        return;
    };
    let rx = inbox.0.lock().unwrap();

    while let Ok(bytes) = rx.try_recv() {
        match *role {
            NetworkRole::Host => {
                if let Ok(msg) = bincode::deserialize::<C2S>(&bytes) {
                    match msg {
                        C2S::PlayerInput(input) => {
                            remote_input.0 = input;
                        }
                        C2S::UpgradeChosen(idx) => {
                            pending_client_choice.0 = Some(idx);
                        }
                    }
                }
            }
            NetworkRole::Client => {
                if let Ok(msg) = bincode::deserialize::<S2C>(&bytes) {
                    match msg {
                        S2C::UpgradeMode(mode_byte) => {
                            *upgrade_mode = UpgradeMode::from_u8(mode_byte);
                        }
                        S2C::StatSnapshot(snap) => {
                            // Stash entity snapshots separately for the sync system.
                            pending_entity_snaps.0 = snap.entities.clone();
                            pending_snap.0 = Some(snap);
                        }
                        S2C::StateChange(new_state) => {
                            pending_state.0 = Some(new_state);
                        }
                        S2C::UpgradeOptions { opts, for_player } => {
                            pending_opts.0 = Some((opts, for_player));
                        }
                        S2C::UpgradeApplied {
                            weapon_type,
                            for_player,
                        } => {
                            pending_applied.0 = Some((weapon_type, for_player));
                        }
                        S2C::WeaponFxSpawned {
                            visual_type,
                            transform,
                            owner_net_id,
                        } => {
                            pending_weapon_fx_events.0.push(S2C::WeaponFxSpawned {
                                visual_type,
                                transform,
                                owner_net_id,
                            });
                        }
                        S2C::WeaponStateChanged {
                            net_id,
                            visual_type,
                            owner_net_id,
                        } => {
                            pending_weapon_state_events.0.push(S2C::WeaponStateChanged {
                                net_id,
                                visual_type,
                                owner_net_id,
                            })
                        }
                    }
                }
            }
            NetworkRole::Solo => {}
        }
    }
}

/// Apply a pending game-state change (received from the host) on the client.
fn apply_pending_state(
    role: Res<NetworkRole>,
    mut pending: ResMut<PendingStateChange>,
    mut next_state: ResMut<NextState<GameState>>,
) {
    if *role != NetworkRole::Client {
        return;
    }
    if let Some(new_state) = pending.0.take() {
        next_state.set(new_state.into());
    }
}

use crate::plugins::audio::{GameAudio, GameAudioEntity};
use crate::plugins::common::aabb_intersects;
use crate::plugins::enemy::{Enemy, XP};
use crate::plugins::game::Atlases;
use crate::plugins::game_state::GameState;
use crate::plugins::network::{
    C2S, NetworkRole, NetOutbox, PendingStatSnapshot, RemoteInput, StatSnapshotMsg, PlayerStat,
    NetworkIdentity, EntitySnapshot, TransformSnapshot,
    encode,
};
use crate::plugins::timers::{MoveTimer, PlayerHealthReduceTimer, GameTimer};
use crate::plugins::weapon_upgrade::LevelUpEvent;
use bevy::audio::{AudioPlayer, PlaybackSettings};
use bevy::camera::primitives::Aabb;
use bevy::image::TextureAtlas;
use bevy::prelude::*;

pub struct PlayerPlugin;

impl Plugin for PlayerPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(
            Update,
            (
                move_player,
                sync_camera.after(move_player),
                reduce_player_health,
                collect_xp_with_magnet,
                magnetite_xp_to_player,
                // Network systems
                send_client_input,
                apply_stat_snapshot,
            )
                .run_if(in_state(GameState::Playing)),
        );
    }
}

#[derive(Component)]
pub struct Player {
    pub health: u32,
    pub max_health: u32,
    pub score: u32,
    pub movement: f32,
    #[allow(unused)]
    pub starting_weapon: String,
    pub xp: f32,
    pub level: i32,
    pub xp_to_next_level: f32,
    /// 0 = Player 1 (WASD / Host), 1 = Player 2 (Arrow keys / Client)
    pub player_index: u8,
}

impl Default for Player {
    fn default() -> Self {
        Self {
            health: 100,
            max_health: 100,
            score: 0,
            movement: 200.,
            starting_weapon: "Flame Thrower".to_string(),
            xp: 0.,
            level: 1,
            xp_to_next_level: 100.,
            player_index: 0,
        }
    }
}

impl Player {
    pub fn take_damage(
        &mut self,
        entity: Entity,
        commands: &mut Commands,
        enemy_query: Query<(&Aabb, &Enemy), (With<Enemy>, Without<Player>)>,
        player_aabb: &Aabb,
    ) {
        for (enemy_aabb, enemy) in enemy_query.iter() {
            if self.health > 0 && aabb_intersects(enemy_aabb, player_aabb) {
                if self.health > 0 {
                    self.health = self.health.saturating_sub(enemy.damage as u32);
                }
            }
        }
        if self.health == 0 {
            commands.entity(entity).despawn();
        }
    }

    pub fn gain_xp(
        &mut self,
        amount: f32,
        message_writer: &mut MessageWriter<LevelUpEvent>,
        next_state: &mut NextState<GameState>,
        commands: &mut Commands,
        audio: &GameAudio,
    ) {
        self.xp += amount;

        if self.xp >= self.xp_to_next_level {
            self.xp -= self.xp_to_next_level;
            self.xp_to_next_level *= 1.5;
            self.level += 1;
            commands.spawn((
                GameAudioEntity,
                AudioPlayer(audio.collect_xp.clone()),
                PlaybackSettings::DESPAWN,
            ));

            message_writer.write(LevelUpEvent {
                level: self.level,
                player_index: self.player_index,
            });
            next_state.set(GameState::UpgradeSelection);
        }
    }
}



#[derive(Component)]
pub struct XPMagnetite;

pub fn collect_xp_with_magnet(
    mut commands: Commands,
    xp_query: Query<Entity, With<XP>>,
    keyboard_input: Res<ButtonInput<KeyCode>>,
) {
    if keyboard_input.just_pressed(KeyCode::KeyC) {
        for entity in xp_query.iter() {
            commands.entity(entity).insert(XPMagnetite);
        }
    }
}

pub fn magnetite_xp_to_player(
    mut xp_query: Query<(&mut Transform, &mut Aabb), (With<XPMagnetite>, Without<Player>)>,
    player_query: Query<(&Transform, &Player), (With<Player>, Without<XPMagnetite>)>,
) {
    // Prefer P1 (player_index == 0) as the magnet target; fall back to any alive player.
    let target = player_query
        .iter()
        .min_by_key(|(_, p)| p.player_index)
        .map(|(t, _)| t.translation);

    let Some(target_pos) = target else {
        return;
    };

    for (mut xp_transform, mut xp_aabb) in xp_query.iter_mut() {
        let direction = (target_pos - xp_transform.translation).normalize();
        xp_transform.translation += direction * 5.;
        xp_aabb.center = xp_transform.translation.into();
    }
}

pub fn move_player(
    mut player_query: Query<(&mut Transform, &Player, &mut Aabb, &mut Sprite), With<Player>>,
    keyboard_input: Res<ButtonInput<KeyCode>>,
    time: Res<Time>,
    atlases: Res<Atlases>,
    enemy_move_timer: Res<MoveTimer>,
    role: Res<NetworkRole>,
    remote_input: Res<RemoteInput>,
) {
    if !atlases.ready {
        return;
    }

    for (mut transform, player, mut aabb, mut sprite) in player_query.iter_mut() {
        if sprite.texture_atlas.is_none() {
            if let Some(layout_handle) = &atlases.body {
                sprite.texture_atlas = Some(TextureAtlas {
                    layout: layout_handle.clone(),
                    index: 0,
                });
            }
        }

        // Determine which input source to use for this player:
        // • Solo: keyboard for both players (original behavior)
        // • Host: keyboard for P1; RemoteInput (from client) for P2
        // • Client: keyboard for P2 only; P1 position arrives via stat snapshot
        let (left, right, up, down) = match *role {
            NetworkRole::Solo => {
                let (kl, kr, ku, kd) = if player.player_index == 0 {
                    (KeyCode::KeyA, KeyCode::KeyD, KeyCode::KeyW, KeyCode::KeyS)
                } else {
                    (KeyCode::ArrowLeft, KeyCode::ArrowRight, KeyCode::ArrowUp, KeyCode::ArrowDown)
                };
                (
                    keyboard_input.pressed(kl),
                    keyboard_input.pressed(kr),
                    keyboard_input.pressed(ku),
                    keyboard_input.pressed(kd),
                )
            }
            NetworkRole::Host => {
                if player.player_index == 0 {
                    (
                        keyboard_input.pressed(KeyCode::KeyA),
                        keyboard_input.pressed(KeyCode::KeyD),
                        keyboard_input.pressed(KeyCode::KeyW),
                        keyboard_input.pressed(KeyCode::KeyS),
                    )
                } else {
                    // P2's input comes from the remote client.
                    let ri = &remote_input.0;
                    (ri.left, ri.right, ri.up, ri.down)
                }
            }
            NetworkRole::Client => {
                if player.player_index == 1 {
                    // Local player on the client.
                    (
                        keyboard_input.pressed(KeyCode::ArrowLeft),
                        keyboard_input.pressed(KeyCode::ArrowRight),
                        keyboard_input.pressed(KeyCode::ArrowUp),
                        keyboard_input.pressed(KeyCode::ArrowDown),
                    )
                } else {
                    // P1 is controlled by the host; skip local movement.
                    continue;
                }
            }
        };

        let mut pos = transform.translation;
        let mut dir: i32 = 5; // 5 = idle

        if left {
            pos.x -= player.movement * time.delta_secs();
            dir = -1;
        }
        if right {
            pos.x += player.movement * time.delta_secs();
            dir = 1;
        }
        if up {
            pos.y += player.movement * time.delta_secs();
            dir = 2;
        }
        if down {
            pos.y -= player.movement * time.delta_secs();
            dir = 0;
        }

        if let Some(ref mut atlas) = sprite.texture_atlas {
            if enemy_move_timer.timer.just_finished() {
                if dir == -1 {
                    atlas.index = 9 + (atlas.index + 1) % 9;
                } else if dir == 1 {
                    atlas.index = 27 + (atlas.index + 1) % 9;
                } else if dir == 2 {
                    atlas.index = (atlas.index + 1) % 9;
                } else if dir == 0 {
                    atlas.index = 18 + (atlas.index + 1) % 9;
                }
            }
        }
        transform.translation = pos;
        aabb.center = transform.translation.to_vec3a();
    }
}

fn sync_camera(
    player_query: Query<&Transform, With<Player>>,
    mut camera_query: Query<&mut Transform, (With<Camera>, Without<Player>)>,
) {
    let positions: Vec<Vec3> = player_query.iter().map(|t| t.translation).collect();
    if positions.is_empty() {
        return;
    }
    let midpoint = positions.iter().copied().sum::<Vec3>() / positions.len() as f32;

    let Ok(mut camera_transform) = camera_query.single_mut() else {
        return;
    };
    camera_transform.translation.x = midpoint.x;
    camera_transform.translation.y = midpoint.y;
}

pub fn reduce_player_health(
    mut commands: Commands,
    mut player_query: Query<(&mut Player, &mut Aabb, Entity), With<Player>>,
    enemy_query: Query<(&Aabb, &Enemy), (With<Enemy>, Without<Player>)>,
    mut player_health_reduce_timer: ResMut<PlayerHealthReduceTimer>,
    time: Res<Time>,
    mut next_state: ResMut<NextState<GameState>>,
    role: Res<NetworkRole>,
) {
    // On the client, health is authoritative from the host snapshot; skip local damage.
    if *role == NetworkRole::Client {
        return;
    }

    player_health_reduce_timer.timer.tick(time.delta());
    if !player_health_reduce_timer.timer.just_finished() {
        return;
    }

    let mut all_dead = true;

    for (mut player, aabb, entity) in player_query.iter_mut() {
        // Apply enemy contact damage.
        for (enemy_aabb, enemy) in enemy_query.iter() {
            if player.health > 0 && aabb_intersects(enemy_aabb, &aabb) {
                player.health = player.health.saturating_sub(enemy.damage as u32);
            }
        }

        if player.health == 0 {
            commands.entity(entity).despawn();
        } else {
            all_dead = false;
        }
    }

    if all_dead {
        next_state.set(GameState::GameOver);
    }
}

// ──────────────────────── Network systems ────────────────────────────────

/// Client: read P2's local keyboard state and send it to the host each frame.
fn send_client_input(
    keyboard: Res<ButtonInput<KeyCode>>,
    role: Res<NetworkRole>,
    outbox: Option<Res<NetOutbox>>,
) {
    if *role != NetworkRole::Client {
        return;
    }
    let Some(outbox) = outbox else { return };

    let input = crate::plugins::network::InputState {
        left: keyboard.pressed(KeyCode::ArrowLeft),
        right: keyboard.pressed(KeyCode::ArrowRight),
        up: keyboard.pressed(KeyCode::ArrowUp),
        down: keyboard.pressed(KeyCode::ArrowDown),
        collect_magnet: keyboard.just_pressed(KeyCode::KeyC),
    };
    if let Ok(frame) = encode(&C2S::PlayerInput(input)) {
        let _ = outbox.0.send(frame);
    }
}

/// Client: apply the latest stat snapshot received from the host.
///
/// The host is authoritative for health, XP, level, score, and **position**.
/// We override local values so the client HUD always shows accurate figures,
/// and move player sprites to match the host's world state.
fn apply_stat_snapshot(
    role: Res<NetworkRole>,
    mut pending: ResMut<PendingStatSnapshot>,
    mut players: Query<(&mut Player, &mut Transform, &mut Aabb)>,
    mut game_timer: ResMut<GameTimer>,
) {
    if *role != NetworkRole::Client {
        return;
    }
    let Some(snap) = pending.0.take() else {
        return;
    };

    // Sync the game clock.
    game_timer.elapsed_secs = snap.game_elapsed_secs;

    for (mut player, mut transform, mut aabb) in players.iter_mut() {
        let (stat, pos): (&PlayerStat, [f32; 2]) = if player.player_index == 0 {
            (&snap.p1, snap.p1_pos)
        } else {
            (&snap.p2, snap.p2_pos)
        };

        // Sync stats.
        player.health = stat.health;
        player.xp = stat.xp;
        player.level = stat.level;
        player.xp_to_next_level = stat.xp_to_next_level;
        player.score = stat.score;

        // Sync position for P1 (authoritative from host).
        // P2's position is handled locally on the client, but we sync it too
        // for consistency — the server's position is always the truth.
        if pos != [0.0_f32, 0.0_f32] {
            transform.translation.x = pos[0];
            transform.translation.y = pos[1];
            aabb.center = transform.translation.to_vec3a();
        }
    }
}

/// Host: build a `StatSnapshotMsg` from the current player components and queue it.
///
/// In addition to player stats, this system gathers the `Transform` of every
/// entity that carries a `NetworkIdentity` and packs them into
/// `StatSnapshotMsg::entities`.  The client's `client_entity_sync` system
/// consumes that list to keep the ghost world in sync.
///
/// Player positions are sent separately as `p1_pos`/`p2_pos` so the client
/// can smoothly move the P1 and P2 sprites.
///
/// Called every frame when running as host so the client stays in sync.
pub fn flush_stat_snapshot(
    role: Res<NetworkRole>,
    outbox: Option<Res<NetOutbox>>,
    players: Query<(&Player, &Transform)>,
    net_entities: Query<(&NetworkIdentity, &Transform)>,
    game_timer: Res<GameTimer>,
) {
    if *role != NetworkRole::Host {
        return;
    }
    let Some(outbox) = outbox else { return };

    let mut msg = StatSnapshotMsg::default();
    for (player, transform) in players.iter() {
        let stat = PlayerStat {
            health: player.health,
            xp: player.xp,
            level: player.level,
            xp_to_next_level: player.xp_to_next_level,
            score: player.score,
        };
        if player.player_index == 0 {
            msg.p1 = stat;
            msg.p1_pos = [transform.translation.x, transform.translation.y];
        } else {
            msg.p2 = stat;
            msg.p2_pos = [transform.translation.x, transform.translation.y];
        }
    }

    // Gather world state: every replicated entity's current transform.
    msg.entities = net_entities
        .iter()
        .map(|(nid, transform)| EntitySnapshot {
            net_id: nid.net_id,
            visual_type: nid.visual_type,
            transform: TransformSnapshot::from_transform(transform),
        })
        .collect();

    // Sync the host's game clock so the client HUD shows the same time.
    msg.game_elapsed_secs = game_timer.elapsed_secs;

    use crate::plugins::network::S2C;
    if let Ok(frame) = encode(&S2C::StatSnapshot(msg)) {
        let _ = outbox.0.send(frame);
    }
}

use crate::plugins::audio::{GameAudio, GameAudioEntity};
use crate::plugins::common::aabb_intersects;
use crate::plugins::enemy::{Enemy, XP};
use crate::plugins::game::Atlases;
use crate::plugins::game_state::GameState;
use crate::plugins::network::{
    C2S, NetworkRole, NetOutbox, PendingStatSnapshot, RemoteInput, StatSnapshotMsg, PlayerStat,
    NetworkIdentity, EntitySnapshot, TransformSnapshot,
    encode,
};
use crate::plugins::timers::{MoveTimer, PlayerHealthReduceTimer, GameTimer};
use crate::plugins::weapon_upgrade::LevelUpEvent;
use bevy::audio::{AudioPlayer, PlaybackSettings};
use bevy::camera::primitives::Aabb;
use bevy::image::TextureAtlas;
use bevy::prelude::*;

pub struct PlayerPlugin;

impl Plugin for PlayerPlugin {
    fn build(&self, app: &mut App) {
        app.add_systems(
            Update,
            (
                move_player,
                sync_camera.after(move_player),
                reduce_player_health,
                collect_xp_with_magnet,
                magnetite_xp_to_player,
                // Network systems
                send_client_input,
                apply_stat_snapshot,
            )
                .run_if(in_state(GameState::Playing)),
        );
    }
}

#[derive(Component)]
pub struct Player {
    pub health: u32,
    pub max_health: u32,
    pub score: u32,
    pub movement: f32,
    #[allow(unused)]
    pub starting_weapon: String,
    pub xp: f32,
    pub level: i32,
    pub xp_to_next_level: f32,
    /// 0 = Player 1 (WASD / Host), 1 = Player 2 (Arrow keys / Client)
    pub player_index: u8,
}

impl Default for Player {
    fn default() -> Self {
        Self {
            health: 100,
            max_health: 100,
            score: 0,
            movement: 200.,
            starting_weapon: "Flame Thrower".to_string(),
            xp: 0.,
            level: 1,
            xp_to_next_level: 100.,
            player_index: 0,
        }
    }
}

impl Player {
    pub fn take_damage(
        &mut self,
        entity: Entity,
        commands: &mut Commands,
        enemy_query: Query<(&Aabb, &Enemy), (With<Enemy>, Without<Player>)>,
        player_aabb: &Aabb,
    ) {
        for (enemy_aabb, enemy) in enemy_query.iter() {
            if self.health > 0 && aabb_intersects(enemy_aabb, player_aabb) {
                if self.health > 0 {
                    self.health = self.health.saturating_sub(enemy.damage as u32);
                }
            }
        }
        if self.health == 0 {
            commands.entity(entity).despawn();
        }
    }

    pub fn gain_xp(
        &mut self,
        amount: f32,
        message_writer: &mut MessageWriter<LevelUpEvent>,
        next_state: &mut NextState<GameState>,
        commands: &mut Commands,
        audio: &GameAudio,
    ) {
        self.xp += amount;

        if self.xp >= self.xp_to_next_level {
            self.xp -= self.xp_to_next_level;
            self.xp_to_next_level *= 1.5;
            self.level += 1;
            commands.spawn((
                GameAudioEntity,
                AudioPlayer(audio.collect_xp.clone()),
                PlaybackSettings::DESPAWN,
            ));

            message_writer.write(LevelUpEvent {
                level: self.level,
                player_index: self.player_index,
            });
            next_state.set(GameState::UpgradeSelection);
        }
    }
}



#[derive(Component)]
pub struct XPMagnetite;

pub fn collect_xp_with_magnet(
    mut commands: Commands,
    xp_query: Query<Entity, With<XP>>,
    keyboard_input: Res<ButtonInput<KeyCode>>,
) {
    if keyboard_input.just_pressed(KeyCode::KeyC) {
        for entity in xp_query.iter() {
            commands.entity(entity).insert(XPMagnetite);
        }
    }
}

pub fn magnetite_xp_to_player(
    mut xp_query: Query<(&mut Transform, &mut Aabb), (With<XPMagnetite>, Without<Player>)>,
    player_query: Query<(&Transform, &Player), (With<Player>, Without<XPMagnetite>)>,
) {
    // Prefer P1 (player_index == 0) as the magnet target; fall back to any alive player.
    let target = player_query
        .iter()
        .min_by_key(|(_, p)| p.player_index)
        .map(|(t, _)| t.translation);

    let Some(target_pos) = target else {
        return;
    };

    for (mut xp_transform, mut xp_aabb) in xp_query.iter_mut() {
        let direction = (target_pos - xp_transform.translation).normalize();
        xp_transform.translation += direction * 5.;
        xp_aabb.center = xp_transform.translation.into();
    }
}

pub fn move_player(
    mut player_query: Query<(&mut Transform, &Player, &mut Aabb, &mut Sprite), With<Player>>,
    keyboard_input: Res<ButtonInput<KeyCode>>,
    time: Res<Time>,
    atlases: Res<Atlases>,
    enemy_move_timer: Res<MoveTimer>,
    role: Res<NetworkRole>,
    remote_input: Res<RemoteInput>,
) {
    if !atlases.ready {
        return;
    }

    for (mut transform, player, mut aabb, mut sprite) in player_query.iter_mut() {
        if sprite.texture_atlas.is_none() {
            if let Some(layout_handle) = &atlases.body {
                sprite.texture_atlas = Some(TextureAtlas {
                    layout: layout_handle.clone(),
                    index: 0,
                });
            }
        }

        // Determine which input source to use for this player:
        // • Solo: keyboard for both players (original behavior)
        // • Host: keyboard for P1; RemoteInput (from client) for P2
        // • Client: keyboard for P2 only; P1 position arrives via stat snapshot
        let (left, right, up, down) = match *role {
            NetworkRole::Solo => {
                let (kl, kr, ku, kd) = if player.player_index == 0 {
                    (KeyCode::KeyA, KeyCode::KeyD, KeyCode::KeyW, KeyCode::KeyS)
                } else {
                    (KeyCode::ArrowLeft, KeyCode::ArrowRight, KeyCode::ArrowUp, KeyCode::ArrowDown)
                };
                (
                    keyboard_input.pressed(kl),
                    keyboard_input.pressed(kr),
                    keyboard_input.pressed(ku),
                    keyboard_input.pressed(kd),
                )
            }
            NetworkRole::Host => {
                if player.player_index == 0 {
                    (
                        keyboard_input.pressed(KeyCode::KeyA),
                        keyboard_input.pressed(KeyCode::KeyD),
                        keyboard_input.pressed(KeyCode::KeyW),
                        keyboard_input.pressed(KeyCode::KeyS),
                    )
                } else {
                    // P2's input comes from the remote client.
                    let ri = &remote_input.0;
                    (ri.left, ri.right, ri.up, ri.down)
                }
            }
            NetworkRole::Client => {
                if player.player_index == 1 {
                    // Local player on the client.
                    (
                        keyboard_input.pressed(KeyCode::ArrowLeft),
                        keyboard_input.pressed(KeyCode::ArrowRight),
                        keyboard_input.pressed(KeyCode::ArrowUp),
                        keyboard_input.pressed(KeyCode::ArrowDown),
                    )
                } else {
                    // P1 is controlled by the host; skip local movement.
                    continue;
                }
            }
        };

        let mut pos = transform.translation;
        let mut dir: i32 = 5; // 5 = idle

        if left {
            pos.x -= player.movement * time.delta_secs();
            dir = -1;
        }
        if right {
            pos.x += player.movement * time.delta_secs();
            dir = 1;
        }
        if up {
            pos.y += player.movement * time.delta_secs();
            dir = 2;
        }
        if down {
            pos.y -= player.movement * time.delta_secs();
            dir = 0;
        }

        if let Some(ref mut atlas) = sprite.texture_atlas {
            if enemy_move_timer.timer.just_finished() {
                if dir == -1 {
                    atlas.index = 9 + (atlas.index + 1) % 9;
                } else if dir == 1 {
                    atlas.index = 27 + (atlas.index + 1) % 9;
                } else if dir == 2 {
                    atlas.index = (atlas.index + 1) % 9;
                } else if dir == 0 {
                    atlas.index = 18 + (atlas.index + 1) % 9;
                }
            }
        }
        transform.translation = pos;
        aabb.center = transform.translation.to_vec3a();
    }
}

fn sync_camera(
    player_query: Query<&Transform, With<Player>>,
    mut camera_query: Query<&mut Transform, (With<Camera>, Without<Player>)>,
) {
    let positions: Vec<Vec3> = player_query.iter().map(|t| t.translation).collect();
    if positions.is_empty() {
        return;
    }
    let midpoint = positions.iter().copied().sum::<Vec3>() / positions.len() as f32;

    let Ok(mut camera_transform) = camera_query.single_mut() else {
        return;
    };
    camera_transform.translation.x = midpoint.x;
    camera_transform.translation.y = midpoint.y;
}

pub fn reduce_player_health(
    mut commands: Commands,
    mut player_query: Query<(&mut Player, &mut Aabb, Entity), With<Player>>,
    enemy_query: Query<(&Aabb, &Enemy), (With<Enemy>, Without<Player>)>,
    mut player_health_reduce_timer: ResMut<PlayerHealthReduceTimer>,
    time: Res<Time>,
    mut next_state: ResMut<NextState<GameState>>,
    role: Res<NetworkRole>,
) {
    // On the client, health is authoritative from the host snapshot; skip local damage.
    if *role == NetworkRole::Client {
        return;
    }

    player_health_reduce_timer.timer.tick(time.delta());
    if !player_health_reduce_timer.timer.just_finished() {
        return;
    }

    let mut all_dead = true;

    for (mut player, aabb, entity) in player_query.iter_mut() {
        // Apply enemy contact damage.
        for (enemy_aabb, enemy) in enemy_query.iter() {
            if player.health > 0 && aabb_intersects(enemy_aabb, &aabb) {
                player.health = player.health.saturating_sub(enemy.damage as u32);
            }
        }

        if player.health == 0 {
            commands.entity(entity).despawn();
        } else {
            all_dead = false;
        }
    }

    if all_dead {
        next_state.set(GameState::GameOver);
    }
}

// ──────────────────────── Network systems ────────────────────────────────

/// Client: read P2's local keyboard state and send it to the host each frame.
fn send_client_input(
    keyboard: Res<ButtonInput<KeyCode>>,
    role: Res<NetworkRole>,
    outbox: Option<Res<NetOutbox>>,
    window: Single<&Window>,
    camera: Query<(&Camera, &GlobalTransform)>,
) {
    if *role != NetworkRole::Client {
        return;
    }
    let Some(outbox) = outbox else { return };

    let mut mouse_world_pos = None;
    if let Ok((cam, cam_transform)) = camera.get_single() {
        mouse_world_pos = window
            .cursor_position()
            .and_then(|pos| cam.viewport_to_world_2d(cam_transform, pos).ok())
            .map(|v| [v.x, v.y]);
    }

    let input = crate::plugins::network::InputState {
        left: keyboard.pressed(KeyCode::ArrowLeft),
        right: keyboard.pressed(KeyCode::ArrowRight),
        up: keyboard.pressed(KeyCode::ArrowUp),
        down: keyboard.pressed(KeyCode::ArrowDown),
        collect_magnet: keyboard.just_pressed(KeyCode::KeyC),
        mouse_world_pos,
    };
    if let Ok(frame) = encode(&C2S::PlayerInput(input)) {
        let _ = outbox.0.send(frame);
    }
}

/// Client: apply the latest stat snapshot received from the host.
///
/// The host is authoritative for health, XP, level, score, and **position**.
/// We override local values so the client HUD always shows accurate figures,
/// and move player sprites to match the host's world state.
fn apply_stat_snapshot(
    role: Res<NetworkRole>,
    mut pending: ResMut<PendingStatSnapshot>,
    mut players: Query<(&mut Player, &mut Transform, &mut Aabb)>,
    mut game_timer: ResMut<GameTimer>,
) {
    if *role != NetworkRole::Client {
        return;
    }
    let Some(snap) = pending.0.take() else {
        return;
    };

    // Sync the game clock.
    game_timer.elapsed_secs = snap.game_elapsed_secs;

    for (mut player, mut transform, mut aabb) in players.iter_mut() {
        let (stat, pos): (&PlayerStat, [f32; 2]) = if player.player_index == 0 {
            (&snap.p1, snap.p1_pos)
        } else {
            (&snap.p2, snap.p2_pos)
        };

        // Sync stats.
        player.health = stat.health;
        player.xp = stat.xp;
        player.level = stat.level;
        player.xp_to_next_level = stat.xp_to_next_level;
        player.score = stat.score;

        // Sync position for P1 (authoritative from host).
        // P2's position is handled locally on the client, but we sync it too
        // for consistency — the server's position is always the truth.
        if pos != [0.0_f32, 0.0_f32] {
            transform.translation.x = pos[0];
            transform.translation.y = pos[1];
            aabb.center = transform.translation.to_vec3a();
        }
    }
}

/// Host: build a `StatSnapshotMsg` from the current player components and queue it.
///
/// In addition to player stats, this system gathers the `Transform` of every
/// entity that carries a `NetworkIdentity` and packs them into
/// `StatSnapshotMsg::entities`.  The client's `client_entity_sync` system
/// consumes that list to keep the ghost world in sync.
///
/// Player positions are sent separately as `p1_pos`/`p2_pos` so the client
/// can smoothly move the P1 and P2 sprites.
///
/// Called every frame when running as host so the client stays in sync.
pub fn flush_stat_snapshot(
    role: Res<NetworkRole>,
    outbox: Option<Res<NetOutbox>>,
    players: Query<(&Player, &Transform)>,
    net_entities: Query<(&NetworkIdentity, &Transform)>,
    game_timer: Res<GameTimer>,
) {
    if *role != NetworkRole::Host {
        return;
    }
    let Some(outbox) = outbox else { return };

    let mut msg = StatSnapshotMsg::default();
    for (player, transform) in players.iter() {
        let stat = PlayerStat {
            health: player.health,
            xp: player.xp,
            level: player.level,
            xp_to_next_level: player.xp_to_next_level,
            score: player.score,
        };
        if player.player_index == 0 {
            msg.p1 = stat;
            msg.p1_pos = [transform.translation.x, transform.translation.y];
        } else {
            msg.p2 = stat;
            msg.p2_pos = [transform.translation.x, transform.translation.y];
        }
    }

    // Gather world state: every replicated entity's current transform.
    msg.entities = net_entities
        .iter()
        .map(|(nid, transform)| EntitySnapshot {
            net_id: nid.net_id,
            visual_type: nid.visual_type,
            transform: TransformSnapshot::from_transform(transform),
        })
        .collect();

    // Sync the host's game clock so the client HUD shows the same time.
    msg.game_elapsed_secs = game_timer.elapsed_secs;

    use crate::plugins::network::S2C;
    if let Ok(frame) = encode(&S2C::StatSnapshot(msg)) {
        let _ = outbox.0.send(frame);
    }
}
